// AÇÃO: monta o e-mail avisando o cliente de que a demanda foi concluída.
// ---- utilitários compartilhados (incluídos pelo gerador nos nós Code que precisam) ----
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const paragrafos = (t) => String(t ?? '').trim().split(/\n{2,}/)
  .map((p) => `<p style="margin:0 0 14px">${esc(p).replace(/\n/g, '<br>')}</p>`).join('');
const emailHtml = ({ titulo, corpo, protocolo }) => `<!doctype html><html lang="pt-BR"><body style="margin:0;background:#f3f5f9;font-family:Segoe UI,Helvetica,Arial,sans-serif;color:#1f2937">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="padding:24px 12px"><tr><td align="center">
<table role="presentation" width="560" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:10px;overflow:hidden;border:1px solid #e3e7ef">
<tr><td style="background:#1d3b8b;color:#ffffff;padding:18px 24px;font-size:17px;font-weight:600">Vértice Cloud · Atendimento</td></tr>
<tr><td style="padding:24px 24px 8px;font-size:15px;line-height:1.55">
<p style="margin:0 0 14px;font-size:17px;font-weight:600">${esc(titulo)}</p>${corpo}</td></tr>
<tr><td style="padding:8px 24px 22px;font-size:12px;color:#6b7280">Protocolo <strong style="color:#1f2937">${esc(protocolo)}</strong> · guarde este número para acompanhar sua solicitação.</td></tr>
</table></td></tr></table></body></html>`;
const fmtData = (iso) => new Date(iso).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
const brl = (n) => (n == null || Number.isNaN(Number(n))) ? 'não informado' : Number(n).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

const d = $input.item.json;
const primeiro = String(d.nome ?? '').split(/\s+/)[0] ?? '';
const corpo = paragrafos(
  `Olá, ${primeiro}!\n\nSua solicitação "${d.assunto}" foi concluída. Se algo ainda não estiver resolvido, é só responder este e-mail que reabrimos o atendimento.\n\nEquipe de Atendimento Vértice Cloud`
);
return {
  json: {
    ...d,
    email_assunto: `[${d.protocolo}] Sua solicitação foi concluída`,
    email_html: emailHtml({ titulo: 'Sua solicitação foi concluída', corpo, protocolo: d.protocolo }),
  },
};
